#!/usr/bin/env sh
# fetch Metro do Porto (PT) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://dadosabertos.cm-porto.pt/dataset/713a680c-9e19-11f1-84ed-6abdb6d5cf34/resource/ed724df6-2dda-467c-a6d5-cb027426d82c/download/horarios_gtfs_mdp_07_09_2026.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
